Rules.InvariantScript:
Set(
    gblRecordSelectedProject,
    LookUp(
        Projects,
        ThisRecord.Project = gblRecordSelectedProject.Project
    )
);
Set(
                gblCurrentUser,
                Patch(
                    gblCurrentUser,
                    {
                        CanEditSelectedProject: And(
                            DataSourceInfo(
                                Projects,
                                DataSourceInfo.CreatePermission
                            ),
                            Coalesce(
                                RecordInfo(
                                    gblRecordSelectedProject,
                                    RecordInfo.EditPermission
                                ),
                                false
                            )
                        )
                    }
                )
            );
Set(
    gblRecordProjectPlanning,
    LookUp(
        'Project Plannings',
        Project.Project = gblRecordSelectedProject.Project
    )
);
UpdateContext(
    {
        locTemporaryRequestState: Blank(),
        locGeneratorsPageSize: 30,
        //variables for Generators
        locIsVisibleRightPanelNewEditGenerator: false,
        locIsVisiblePopUpConfirmationDeleteGeneratorType: false,
        locIsVisiblePopUpDeleteGeneratorInProject: false,
        locIsVisiblePopUpInformationGeneratorInProject: false,
        locSelectedGeneratorEntity: Blank(),
        locGeneratorNamePrefix: Blank(),
        //variables for Inverter
        locIsVisibleRightPanelNewEditInverter: false,
        locSelectedInverterTypeEntity: Blank(),
        locSaveInverterButtonEnabled: false,
        locIsVisiblePopUpConfirmationDeleteInverterType: false,
        //variables for Substructure
        locIsVisibleRightPanelNewEditSubstructure: false,
        locSelectedSubstructureTypeEntity: Blank(),
        locSaveSubstructureButtonEnabled: false,
        locIsVisiblePopUpConfirmationDeleteSubstructureType: false,
        //variables PVModule
        locSelectedPvModuleTypeEntity: Blank(),
        locIsVisiblePopUpConfirmationDeletePVModuleType: false,
        locIsVisibleGeneratorLongOperationProcessingDialog: false,
        locGeneratorLongOperationProcessingDialogText: Blank(),
        //variables information dialog
        locGeneratorInformationDialog: false,
        locGeneratorInformationDialogTitle: Blank(),
        locGeneratorInformationDialogText: Blank(),
        locIsVisiblePopUpChangeStatusOfGenerator: false,
        locApplyAllWTGcapacities: false,
        locApplyAllWTGHugHeights: false,
        //this is for PBI 1892
        locSelectedStorageTypeEntity: Blank(),
        locIsVisibleRightPanelNewEditStorageCapacity: false,
        locIsVisiblePopUpConfirmationDeleteStorageInProject: false,
        // for hydrogen
        locSelectedHydrogenTypeEntity: Blank(),
        locIsVisibleRightPanelNewEditHydrogenCapacity: false,
        locIsVisiblePopUpConfirmationDeleteHydrogenInProject: false,
        //for Substation 
        locSelectedSubstationTypeEntity: Blank(),
        locIsVisibleRightPanelNewEditSubstationCapacity: false,
        locIsVisiblePopUpConfirmationDeleteSubstationInProject: false,
        locProjectPlanning: LookUp(
            'Project Plannings',
            Project.Project = gblRecordSelectedProject.Project
        )
    }
);
Concurrent(

    ClearCollect(
        colGeneratorTypeInProjects,
        AddColumns(
            Sort(
                Filter(
                    GeneratorTypeInProjects,
                    Project.Project = gblRecordSelectedProject.Project
                ),
                'Created On',
                SortOrder.Ascending
            ),
            IsFolded,
            true
        )
    ),
    ClearCollect(
        colPVModuleTypesInProjects,
        AddColumns(
            SortByColumns(
                Filter(
                    PVModuleTypeInProjects,
                    Project.Project = gblRecordSelectedProject.Project
                ),
                "createdon",
                SortOrder.Ascending,
                "vsb_name",
                SortOrder.Ascending
            ),
            IsFolded,
            true
        )
    ),
    ClearCollect(
        colInverterTypesInProjects,
        AddColumns(
            Filter(
                InverterTypeInProjects,
                Project.Project = gblRecordSelectedProject.Project
            ),
            IsFolded,
            true
        )
    ),
    ClearCollect(
        colSubstructureTypesInProjects,
        AddColumns(
            Filter(
                SubstructureTypeInProjects,
                Project.Project = gblRecordSelectedProject.Project
            ),
            IsFolded,
            true
        )
    );
    ClearCollect(
        colStorageTypesInProjects,
        AddColumns(
            Filter(
                StorageTypeInProjects,
                Project.Project = gblRecordSelectedProject.Project
            ),
            IsFolded,
            true
        )
    );
    ClearCollect(
        colHydrogenTypesInProjects,
        AddColumns(
            Filter(
                HydrogenTypeInProjects,
                Project.Project = gblRecordSelectedProject.Project
            ),
            IsFolded,
            true
        )
    );
    ClearCollect(
        colSubstationTypesInProjects,
        AddColumns(
            Filter(
                SubstationTypeInProjects,
                Project.Project = gblRecordSelectedProject.Project
            ),
            IsFolded,
            true
        )
    );

);
ClearCollect(
    colGeneratorTypesPagging,
    ForAll(
        colGeneratorTypeInProjects,
        {
            Id: ThisRecord.GeneratorTypeInProject,
            Event: "",
            TotalRows: ThisRecord.'Number of Generators',
            Page: 1,
            Pages: 0,
            PageSize: locGeneratorsPageSize
        }
    )
);
With(
    {
        varFilteredGenerators: AddColumns(
            Filter(
                GeneratorInProjects,
                And(
                    Not(IsEmpty(colGeneratorTypeInProjects)),
                    AsType(
                        ModuleTypeInProject,
                        GeneratorTypeInProjects
                    ).GeneratorTypeInProject in colGeneratorTypeInProjects.GeneratorTypeInProject
                )
            ),
            GeneartorName,
            Name,
            Index,
            Value(
                Last(
                    Split(
                        Name,
                        "_"
                    )
                ).Value
            )
        )
    },
    ClearCollect(
        colGeneratorsInProjectsTemporary,
        varFilteredGenerators
    );
    Trace(
        $"Info: Generators types are collected {CountIf(
            colGeneratorsInProjectsTemporary,
            true
        )}...",
        TraceSeverity.Critical
    )
);
Set(
    gblRecordEstimationPriceInflationDirect,
    LookUp(
        'Estimation Price Inflations',
        'FID Year' = Year(gblRecordSelectedProject.'Final Investment Decision')
    )
);
Set(
    gblRecordEstimationPriceInflationDirectPrevious,
    LookUp(
        'Estimation Price Inflations',
        'FID Year' = Year(gblRecordSelectedProject.'Final Investment Decision') - 1
    )
);
ClearCollect(
    colDeviceCosts,
    'Device Costs'
);
Set(
    gblEstimationPriceInflationDirectConstants,
    Blank()
);
With(
    {
        varIsoCurrencyCode: If(
            Not(IsBlank(gblRecordSelectedProjectCountry.'ISO Currency Code')),
            gblRecordSelectedProjectCountry.'ISO Currency Code',
            "EUR"
        )
    },
    Set(
        gblDiviceCoststConstants,
        {
            Modules: Value(
                LookUp(
                    colDeviceCosts,
                    'Device Type' = "Modules"
                ).'Device Cost [EUR/MWp]'
            ),
            Inverter: Value(
                LookUp(
                    colDeviceCosts,
                    'Device Type' = "Inverter"
                ).'Device Cost [EUR/MWp]'
            ),
            MountingSystemsFix: Value(
                LookUp(
                    colDeviceCosts,
                    'Device Type' = "Mounting systems fix"
                ).'Device Cost [EUR/MWp]'
            ),
            MountingSystemsTracker: Value(
                LookUp(
                    colDeviceCosts,
                    'Device Type' = "Mounting systems tracker"
                ).'Device Cost [EUR/MWp]'
            )
        }
    )
);
Set(
    gblEstimationPriceInflationDirectConstants,
    {
        AdditionalCost: {
            Year: Year(gblRecordSelectedProject.'Final Investment Decision'),
            PreviousYear: Year(gblRecordSelectedProject.'Final Investment Decision') - 1,
            MonthIndex: Month(gblRecordSelectedProject.'Final Investment Decision') / 12,
            AnnualPriceEscalationIndex: gblRecordEstimationPriceInflationDirect.'Annual Price Escalation Index',
            AccumulatedPriceEscalationIndex: gblRecordEstimationPriceInflationDirect.'Accumulated Price Escalation Index',
            AccumulatedPriceEscalationIndexPrevious: gblRecordEstimationPriceInflationDirectPrevious.'Accumulated Price Escalation Index',
            AccumulatedIndex: (gblRecordEstimationPriceInflationDirectPrevious.'Accumulated Price Escalation Index' + (gblRecordEstimationPriceInflationDirect.'Accumulated Price Escalation Index' - gblRecordEstimationPriceInflationDirectPrevious.'Accumulated Price Escalation Index') * Month(gblRecordSelectedProject.'Final Investment Decision') / 12)
        }
    }
);
ClearCollect(
    colPanelGeneratorFormValidation,
    Blank()
);
ClearCollect(
    colPanelWtgFormValidation,
    Blank()
);
ClearCollect(
    colPanelInverterFormValidation,
    Blank()
);
ClearCollect(
    colPanelStorageFormValidation,
    Blank()
);
ClearCollect(
    colPanelHydrogenFormValidation,
    Blank()
);
ClearCollect(
    colPanelSubstationFormValidation,
    Blank()
);
ClearCollect(
    colTemporaryGeneratorList,
    Blank()
);
ClearCollect(
    colGenerators,
    Generators
);
ClearCollect(
    colGeneratorsInProjectsTemp,
    With(
        {
            locFilteredGeneratorsList: AddColumns(
                ShowColumns(
                    colGenerators,
                    Supplier,
                    Status,
                    Name,
                    Indexation,
                    GeneratorTypeInProjects,
                    Generator,
                    DisplayName,
                    'Country availability',
                    'Earliest phaseout',
                    'Length of period for availability calculation',
                    'Turbine Type',
                    'Hub Height'
                ),
                Availability,
                Concat(
                    ThisRecord.vsb_countryavailability,
                    Value & ","
                ),
                FullDisplayName,
                Concatenate(
                    vsb_displayname,
                    Text(
                        vsb_earliestphaseout,
                        "mm.dd.yyyy"
                    ),
                    " - Latest possible order",
                    If(
                        And(
                            Not(IsBlank(ThisRecord.vsb_countryavailability)),
                            gblRecordSelectedProject.Country.Name in Concat(
                                ThisRecord.vsb_countryavailability,
                                Value & ","
                            )
                        ),
                        " - available",
                        " - not available"
                    )
                ),
                IsAvailabile,
                And(
                    Not(IsBlank(ThisRecord.vsb_countryavailability)),
                    gblRecordSelectedProject.Country.Name in Concat(
                        ThisRecord.vsb_countryavailability,
                        Value & ","
                    )
                )
            )
        },
        SortByColumns(
            Filter(
                locFilteredGeneratorsList,
                And(
                    Not(IsBlank(gblRecordSelectedProject.'Final Investment Decision')),
                    ThisRecord.vsb_earliestphaseout > gblRecordSelectedProject.'Final Investment Decision'
                )
            ),
            "vsb_displayname",
            SortOrder.Ascending
        )
    )
);
ClearCollect(
    colDummyTypes,
    Table(
        {
            Id: 1,
            Value: "Type 1"
        },
        {
            Id: 2,
            Value: "Type 2"
        },
        {
            Id: 3,
            Value: "Type 3"
        }
    )
)

