Clear(colGeneratorTypeInProjects);
Clear(colGeneratorsInProjectsTemporary);
//clear for PVModules
Clear(colPVModuleTypesInProjects);
Clear(colInverterTypesInProjects);
Clear(colSubstructureTypesInProjects);
Clear(colStorageTypesInProjects);
Clear(colHydrogenTypesInProjects);
Clear(colSubstationTypesInProjects);
UpdateContext(
    {
        locTemporaryRequestState: Blank(),
        //variables for Generators
        locIsVisibleRightPanelNewEditGenerator: false,
        locIsVisiblePopUpConfirmationDeleteGeneratorType: false,
        locIsVisiblePopUpDeleteGeneratorInProject: false,
        locIsVisiblePopUpInformationGeneratorInProject: false,
        locSelectedGeneratorEntity: Blank(),
        locGeneratorNamePrefix: Blank(),
        //variables for Inverter
        locIsVisibleRightPanelNewEditInverter: false,
        locSelectedInverterTypeEntity: Blank(),
        locSaveInverterButtonEnabled: false,
        locIsVisiblePopUpConfirmationDeleteInverterType: false,
        //variables for Substructure
        locIsVisibleRightPanelNewEditSubstructure: false,
        locSelectedSubstructureTypeEntity: Blank(),
        locSaveSubstructureButtonEnabled: false,
        locIsVisiblePopUpConfirmationDeleteSubstructureType: false,
        //variables PVModule
        locSelectedPvModuleTypeEntity: Blank(),
        locIsVisiblePopUpConfirmationDeletePVModuleType: false,
        locSelectedStorageTypeEntity: Blank(),
        locIsVisibleRightPanelNewEditStorageCapacity: false,
        // for hydrogen
        locSelectedHydrogenTypeEntity: Blank(),
        locIsVisibleRightPanelNewEditHydrogenCapacity: false,
        //for Substation 
        locSelectedSubstationTypeEntity: Blank(),
        locIsVisibleRightPanelNewEditSubstationCapacity: false
    }
);
Set(
    gblRecordProjectPlanning,
    Blank()
);

