UpdateContext(
    {
        locGeneratorTabList: ForAll(
            Filter(
                GenertatorInProjects,
                'GenertatorInProjects (Views)'.'Aktive GenertatorInProjects',
                ThisRecord.ProjectId.Project = SelectedProject.Project
            ),
            {
                TabName: Concatenate(ThisRecord.'Generator Id'.Manufacturer, " ", ThisRecord.'Generator Id'.Label),
