        Trace(
            $"Cancelation of Generator, ModuleTypeGuid: {varModule.ModuleTypeGuid}, FlowRunId: {varModule.FlowRunId}, FlowApprovalId: {varModule.FlowApprovalId}",
            TraceSeverity.Information
        );
        UpdateContext(
            {
                locFlowRequestPermissionCanceled: Requestpermissioncancellation.Run(
                    User().Email,
                    gblProjectManagmentAppID,
                    JSON(varModule)
                )
            }
        );
        With(
            {
                varCanceledState: LookUp(
                    Choices('Request Permission State'),
                    Value = gblAppConstants.RequestPermission.PermissionCanceled
                ).Value
            },
            UpdateContext(
                {
                    locSelectedGeneratorEntity: Patch(
                        GeneratorTypeInProjects,
                        LookUp(
                            GeneratorTypeInProjects,
                            ThisRecord.GeneratorTypeInProject = locSelectedGeneratorEntity.GeneratorTypeInProject
