                        {'Request Permission State': varCanceledState}
                    )
                }
            );
            UpdateIf(
                colGeneratorTypeInProjects,
                GeneratorTypeInProject = ThisItem.GeneratorTypeInProject,
                {
                    'Request Permission State': varCanceledState,
                    FlowApprovalId: Blank()
                }
            )
        );
    );
    Notify(
        $"Request permisson forg generator {ThisItem.Generator.DisplayName} was canceled !",
        NotificationType.Success,
        2000
    ),
    Notify(
        "Error: Current project cannot be send to controlling for approval. " & "Internal error: originated on " & FirstError.Source & ". Message: " & FirstError.Message & FirstError.Details.HttpResponse,
