IfError(
    With(
        {
            varNumberOfInverters: Value(txt_GeneratorData_RightPanel_Form_Inverter_Fields_NumberOfInverters.Value),
            varNominalPower: Value(txt_GeneratorData_RightPanel_Form_Inverter_Fields_NominalPower.Value)
        },
        With(
            {
                varCostsPerInverter: If(
                    Not(IsBlank(gblDiviceCoststConstants.Inverter)),
                    Value(Value(gblDiviceCoststConstants.Inverter) * varNominalPower / 1000),
                    0
                )
            },
            UpdateContext(
                {
                    locSelectedInverterTypeEntity: Patch(
                        InverterTypeInProjects,
                        If(
                            IsBlank(locSelectedInverterTypeEntity),
                            Defaults(InverterTypeInProjects),
                            locSelectedInverterTypeEntity
                        ),
                        {
                            Project: gblRecordSelectedProject,
                            Inverter: cmb_GeneratorData_RightPanel_Form_Inverter_Fields_Supplier.Selected,
                            'Inverter Label': txt_GeneratorData_RightPanel_Form_Inverter_Fields_Label.Value,
                            'Other Supplier': txt_GeneratorData_RightPanel_Form_Inverter_Fields_OtherSupplier.Value,
                            'Inverter Types': cmb_GeneratorData_RightPanel_Form_Inverter_Fields_InverterType.SelectedItems,
                            'Warranty [Years]': Value(txt_GeneratorData_RightPanel_Form_Inverter_Fields_Warranty.Value),
                            'Number of Inverters': varNumberOfInverters,
                            'Nominal Power [kW]': varNominalPower,
                            'Costs per Inverter [EUR/Inverter]': varCostsPerInverter,
                            'Inverter Type Cost': Value(varCostsPerInverter * varNumberOfInverters),
                            'Owning Business Unit': gblRecordSelectedProject.'Besitzer (Unternehmenseinheit)'
                        }
                    )
                }
            )
        )
    );
    ClearCollect(
        colInverterTypesInProjects,
        AddColumns(
            Filter(
                InverterTypeInProjects,
                Project.Project = gblRecordSelectedProject.Project
            ),
            IsFolded,
            If(
                ThisRecord.InverterTypeInProject = locSelectedInverterTypeEntity.InverterTypeInProject,
                false,
                true
            )
        )
    );
    If(
        Not(IsBlank(txt_GeneratorData_RightPanel_Form_Inverter_Fields_OtherSupplier.Value)),
        // Start flow to request invertrs permissions. Update project Plant WTG Capacity/Cost only for available geneartors. For requested inverterss SUM will be calculated in flow, if inverter will be approved
        With(
            {
                varProject: {
                    ProjectGuid: gblRecordSelectedProject.Project,
                    ProjectId: gblRecordSelectedProject.'Project ID',
                    ProjectName: gblRecordSelectedProject.'Project Name',
                    ShortName: gblRecordSelectedProject.'Short Name',
                    ProjectManagerEmail: gblRecordSelectedProject.'Project Manager'.Mail,
                    ModuleType: gblAppConstants.ModuleType.Inverter,
                    InverterTypeInProject: locSelectedInverterTypeEntity.InverterTypeInProject
                }
            },
            Set(
                gblFlowRequestModuleTypeInProject,
                RequestModulePermission.Run(
                    User().Email,
                    gblPrimarilyApprovalGroupID,
                    gblProjectManagmentAppID,
                    JSON(varProject)
                )
            )
        );
        UpdateIf(
            colInverterTypesInProjects,
            InverterTypeInProject = locSelectedInverterTypeEntity.InverterTypeInProject,
            {
                'Request Permission State': LookUp(
                    Choices('Request Permission State'),
                    Value = gblAppConstants.RequestPermission.PermissionPending
                ).Value,
                FlowRunId: gblFlowRequestModuleTypeInProject.runid,
                FlowApprovalId: gblFlowRequestModuleTypeInProject.approvalid
            }
        ),
        // If not requested permissions, update project PV Plant Costs/Capacity
        Set(
            gblRecordSelectedProject,
            Patch(
                Projects,
                gblRecordSelectedProject,
                {
                    'Plant PV Cost [EUR]': Value(
                        Sum(
                            Sum(
                                colPVModuleTypesInProjects,
                                'Cost [EUR]'
                            ),
                            Sum(
                                colInverterTypesInProjects,
                                'Inverter Type Cost'
                            ),
                            Sum(
                                colSubstructureTypesInProjects,
                                'Substructure Cost [EUR]'
                            )
                        )
                    )
                }
            )
        );
    );
    Notify(
        "Inverter type was successfully saved for current project!",
        NotificationType.Success,
        2000
    ),
    Notify(
        "Error: Inverter type could not be saved. " & "Internal error: originated on " & FirstError.Source & ". Message: " & FirstError.Message & FirstError.Details.HttpResponse,
        NotificationType.Error
    )
);
UpdateContext(
