                        // 'Effective Hub Height Changed': locSelectedGeneratorEntity.Generator.'Hub Height' <> Value(txt_GeneratorData_RightPanel_Form_Fields_Effective_HubHeight.Value),
'Hub Height excl. Foundation Plinth [m]': Value(txt_GeneratorData_RightPanel_Form_Fields_Effective_HubHeight.Value),
                        'Owning Business Unit': gblRecordSelectedProject.'Besitzer (Unternehmenseinheit)',
                        'Foundation Plinth [m]': Value(txt_GeneratorData_RightPanel_Form_Fields_Foundation_Plinth.Value),
