                )
            },
            If(
                varFoundationCostIncluded = "Yes",
                UpdateContext(
                    {
                        locGeneratorCostsPerWtgFormula: $"{varGeneratorCostsPerWtgNet} * {varAccumulatedPriceFormula}",
                        locGeneratorCostsPerWtg: Switch(
                            Value(Self.Value),
                            1,
                            varGeneratorCostsPerWtgNet * varAccumulatedPrice,
                            2,
                            varGeneratorCostsPerWtgNet * varAccumulatedPrice,
                            3,
                            varGeneratorCostsPerWtgNet * varAccumulatedPrice,
                            4,
                            varGeneratorCostsPerWtgNet * varAccumulatedPrice,
                            varGeneratorCostsPerWtgNet * varAccumulatedPrice
                        )
                    }
