                UpdateContext(
                    {
                        locGeneratorCostsPerWtgFormula: $"({varGeneratorCostsPerWtgNet} + {varAdditionalCost}) * {varAccumulatedPriceFormula}",
                        locGeneratorCostsPerWtg: Switch(
                            Value(Self.Value),
                            1,
                            (varGeneratorCostsPerWtgNet + varAdditionalCost) * varAccumulatedPrice,
                            2,
                            (varGeneratorCostsPerWtgNet + varAdditionalCost) * varAccumulatedPrice,
                            3,
                            (varGeneratorCostsPerWtgNet + varAdditionalCost) * varAccumulatedPrice,
                            4,
                            (varGeneratorCostsPerWtgNet + varAdditionalCost) * varAccumulatedPrice,
                            (varGeneratorCostsPerWtgNet + varAdditionalCost) * varAccumulatedPrice
                        )
                    }
