                                GeneratorTypeInProject: varCreatedGeneratorEntity.GeneratorTypeInProject,
                                Generator: varCreatedGeneratorEntity.Generator.Generator
                            }
                        },
                        Set(
                            gblFlowRequestModuleTypeInProject,
                            RequestModulePermission.Run(
