                            $"G007: Generator data {locSelectedGeneratorEntity.Name} was updated, Record to calculate: {CountRows(varColCurrentRecords)}; {JSON(
                                ShowColumns(
                                    varColCurrentRecords,
                                    Name,
                                    'Number of Generators',
                                    Status
                                )
                            )}...",
                            TraceSeverity.Information
                        );
                        Set(
                            gblRecordSelectedProject,
                            Patch(
                                Projects,
                                gblRecordSelectedProject,
                                {
                                    'Plant WTG Capacity [MW]': Sum(
                                        varColCurrentRecords,
                                        'Generators Capacity'
                                    ),
                                    'Plant WTG Cost [EUR]': Sum(
                                        varColCurrentRecords,
                                        'Generators Cost'
                                    )
                                }
                            )
                        )
                    );
                );
                UpdateContext(
                // Set local variable generator type.
                    {
                        locSelectedGeneratorEntity: LookUp(
                            colGeneratorTypeInProjects,
                            GeneratorTypeInProject = varCreatedGeneratorEntity.GeneratorTypeInProject
                        )
                    }
                );
            )
        );
        Reset(cmb_Supplier);
        Reset(cmb_Supplier_1);
        Reset(cmb_Supplier_2);
        Reset(txt_GeneratorData_RightPanel_Form_Fields_NumberOfGenerator);
        Reset(txt_GeneratorData_RightPanel_Form_Fields_HubHeight_1);
        Notify(
            "Generator type was successfully saved for current project!",
            NotificationType.Success,
            2000
        ),
        Notify(
            "Error: Generator type could not be saved. " & "Internal error: originated on " & FirstError.Source & ". Message: " & FirstError.Message & FirstError.Details.HttpResponse,
            NotificationType.Error
        )
