Rules.InvariantScript:
IfError(
    With(
        {
            WTGsToDelete: Filter(
                'Land Lease Allocation WTGS',
                'Generator In Project'.GeneratorInProject = locSelectedGeneratorInProject.GeneratorInProject
            )
        },
        ForAll(
            WTGsToDelete As WTG,
            If(
                CountRows(
                    Filter(
                        'Land Lease Allocation WTGS',
                        'Project Cost'.'Land Lease Project Cost' = WTG.'Project Cost'.'Land Lease Project Cost'
                    )
                ) > 1,
                // If there are multiple WTGs associated with Project Cost, then the Project Cost cannot be deleted. Only WTG record can be deleted
                Remove(
                    'Land Lease Allocation WTGS',
                    WTG
                ),
                // If there is only one WTG associated with Project Cost, then the Project Cost record can be deleted. WTG will be deleted as well due to the Parental relationship
                Remove(
                    'Land Lease Project Costs',
                    WTG.'Project Cost'
                )
            )
        );
    );
    Remove(
        GeneratorInProjects,
        locSelectedGeneratorInProject
    );
    Refresh(GeneratorInProjects);
    With(
        {
            varRecordGenerator: locSelectedGeneratorEntity.Generator,
            varNumberOfGenerators: CountRows(
                Filter(
                    GeneratorInProjects,
                    AsType(
                        ModuleTypeInProject,
                        GeneratorTypeInProjects
                    ).GeneratorTypeInProject = locSelectedGeneratorEntity.GeneratorTypeInProject
                )
            ),
            varSpecificCapacity: Sum(
                Filter(
                    GeneratorInProjects,
                    AsType(
                        ModuleTypeInProject,
                        GeneratorTypeInProjects
                    ).GeneratorTypeInProject = locSelectedGeneratorEntity.GeneratorTypeInProject
                ),
                'Effective Capacity'
            )
        },
        With(
            {
                varAccumulatedPrice: gblEstimationPriceInflationDirectConstants.AdditionalCost.AccumulatedIndex,
                varFoundationCostIncluded: Text(varRecordGenerator.'Foundation cost included'),
                varAdditionalCost: Value(varRecordGenerator.'Additional foundation cost'),
                varGeneratorCostsPerWtgNet: Switch(
                    Value(varNumberOfGenerators),
                    1,
                    varRecordGenerator.'1 WTG price',
                    2,
                    varRecordGenerator.'2 WTG price',
                    3,
                    varRecordGenerator.'3 WTG price',
                    4,
                    varRecordGenerator.'4 WTG price',
                    varRecordGenerator.'5 WTG price'
                )
            },
            If(
                varFoundationCostIncluded = "Yes",
                UpdateContext(
                    {
                        locNumberOfGenerators: varNumberOfGenerators,
                        locGeneratorCostsPerWtg: Switch(
                            Value(varNumberOfGenerators),
                            1,
                            varGeneratorCostsPerWtgNet * varAccumulatedPrice,
                            2,
                            varGeneratorCostsPerWtgNet * varAccumulatedPrice,
                            3,
                            varGeneratorCostsPerWtgNet * varAccumulatedPrice,
                            4,
                            varGeneratorCostsPerWtgNet * varAccumulatedPrice,
                            varGeneratorCostsPerWtgNet * varAccumulatedPrice
                        ),
                        locSpecificCapacity: varSpecificCapacity
                    }
                ),
                UpdateContext(
                    {
                        locNumberOfGenerators: varNumberOfGenerators,
                        locGeneratorCostsPerWtg: Switch(
                            Value(varNumberOfGenerators),
                            1,
                            (varGeneratorCostsPerWtgNet + varAdditionalCost) * varAccumulatedPrice,
                            2,
                            (varGeneratorCostsPerWtgNet + varAdditionalCost) * varAccumulatedPrice,
                            3,
                            (varGeneratorCostsPerWtgNet + varAdditionalCost) * varAccumulatedPrice,
                            4,
                            (varGeneratorCostsPerWtgNet + varAdditionalCost) * varAccumulatedPrice,
                            (varGeneratorCostsPerWtgNet + varAdditionalCost) * varAccumulatedPrice
                        ),
                        locSpecificCapacity: varSpecificCapacity
                    }
                )
            )
        )
    );
    UpdateContext(
        {
            locSelectedGeneratorEntity: Patch(
                GeneratorTypeInProjects,
                LookUp(
                    GeneratorTypeInProjects,
                    GeneratorTypeInProject = locSelectedGeneratorEntity.GeneratorTypeInProject
                ),
                {
                    Project: gblRecordSelectedProject,
                    'Number of Generators': locNumberOfGenerators,
                    'Cost per WTG': If(
                        locNumberOfGenerators <> 0,
                        locGeneratorCostsPerWtg,
                        0
                    ),
                    'Generators Cost': locNumberOfGenerators * locGeneratorCostsPerWtg,
                    'Generators Capacity': locSpecificCapacity,
                    'Owning Business Unit': gblRecordSelectedProject.'Besitzer (Unternehmenseinheit)'
                }
            )
        }
    );
    Patch(
        colGeneratorTypeInProjects,
        LookUp(
            colGeneratorTypeInProjects,
            GeneratorTypeInProject = locSelectedGeneratorEntity.GeneratorTypeInProject
        ),
        {
            Project: gblRecordSelectedProject,
            'Number of Generators': locNumberOfGenerators,
            'Cost per WTG': If(
                locNumberOfGenerators <> 0,
                locGeneratorCostsPerWtg,
                0
            ),
            'Generators Cost': locNumberOfGenerators * locGeneratorCostsPerWtg,
            'Generators Capacity': locSpecificCapacity
        }
    );
    With(
        {varGeneratorsNumber: locNumberOfGenerators},
        UpdateIf(
            colGeneratorTypesPagging,
            Id = locSelectedGeneratorEntity.GeneratorTypeInProject,
            {
                Event: Blank(),
                TotalRows: varGeneratorsNumber,
                Page: 1,
                Pages: RoundUp(
                    varGeneratorsNumber / locGeneratorsPageSize,
                    0
                ) + If(
                    varGeneratorsNumber = 0,
                    1
                ),
                PageSize: locGeneratorsPageSize
            }
        )
    );
    With(
        {
            varColCurrentRecords: Filter(
                colGeneratorTypeInProjects,
                And(
                    Or(
                        IsBlank('Request Permission State'),
                        'Request Permission State' = gblAppConstants.RequestPermission.PermissionApproved
                    ),
                    Status = 'Status (GeneratorTypeInProjects)'.Active
                )
            )
        },
        Trace(
            $"G003: Generator data {locSelectedGeneratorEntity.Name} was updated, Record to calculate: {CountRows(varColCurrentRecords)}...",
            TraceSeverity.Information
        );
        Set(
            gblRecordSelectedProject,
            Patch(
                Projects,
                gblRecordSelectedProject,
                {
                    'Plant WTG Capacity [MW]': Sum(
                        varColCurrentRecords,
                        'Generators Capacity'
                    ),
                    'Plant WTG Cost [EUR]': Sum(
                        varColCurrentRecords,
                        'Generators Cost'
                    )
                }
            )
        )
    );
    With(
        {
            varFilteredGenerators: AddColumns(
                Filter(
                    GeneratorInProjects,
                    AsType(
                        ModuleTypeInProject,
                        GeneratorTypeInProjects
                    ).GeneratorTypeInProject in colGeneratorTypeInProjects.GeneratorTypeInProject
                ),
                GeneartorName,
                Name,
                Index,
                Value(
                    Last(
                        Split(
                            Name,
                            "_"
                        )
                    ).Value
                )
            )
        },
        ClearCollect(
            colGeneratorsInProjectsTemporary,
            varFilteredGenerators
        )
    );
    UpdateContext(
        {
            locGeneratorsGridTotalRows: CountRows(
                Filter(
                    GeneratorInProjects,
                    AsType(
                        ModuleTypeInProject,
                        GeneratorTypeInProjects
                    ).GeneratorTypeInProject = locSelectedGeneratorEntity.GeneratorTypeInProject
                )
            )
        }
    );
    Notify(
        "Generator and related Land Leases have been successfully deleted.",
        NotificationType.Success,
        gblAppConstants.DefNotifyTimeoutMilliseconds
    ),
    Notify(
        "Error: Generator could not be deleted. " & "Internal error: originated on " & FirstError.Source & ". Message: " & FirstError.Message & FirstError.Details.HttpResponse,
        NotificationType.Error
    )
);
UpdateContext(
    {
        locSelectedGeneratorInProject: Blank(),
        locIsVisiblePopUpDeleteGeneratorInProject: false
    }
);

