Rules.InvariantScript:
UpdateContext(
    {
        locHeightLimitationApproval: true,
        locIsVisibleHeightLimitationApproval: false
    }
);
UpdateContext(
    {
        locIsVisibleGeneratorLongOperationProcessingDialog: true,
        locGeneratorLongOperationProcessingDialogText: If(
            tgl_btn_GeneratorData_RightPanel_Form_Filter_Country.Checked,
            $"Generator '{locNewGeneratorEntity.DisplayName}' will be saved, please wait...",
            $"Request Permission for '{locNewGeneratorEntity.DisplayName}' has been sent, please wait..."
        )
    }
);
IfError(
    With(
        {
            varNumberOfGenerators: Value(txt_GeneratorData_RightPanel_Form_Fields_NumberOfGenerator.Value),
            varCostWTg: Value(txt_GeneratorData_RightPanel_Form_Fields_Cost.Value),
            varSpecificCapacity: If(
                Not(IsBlank(locNewGeneratorEntity.'Specific Capacity')),
                Value(locNewGeneratorEntity.'Specific Capacity'),
                0
            )
        },
        With(
            {
                varCreatedGeneratorEntity: Patch(
                    GeneratorTypeInProjects,
                    If(
                        IsBlank(locSelectedGeneratorEntity),
                        Defaults(GeneratorTypeInProjects),
                        LookUp(
                            GeneratorTypeInProjects,
                            GeneratorTypeInProject = locSelectedGeneratorEntity.GeneratorTypeInProject
                        )
                    ),
                    {
                        Project: gblRecordSelectedProject,
                        Generator: locNewGeneratorEntity,
                        'Number of Generators': varNumberOfGenerators,
                        'Cost per WTG': varCostWTg,
                        'Generators Cost': varNumberOfGenerators * varCostWTg,
                        'Generators Capacity': varNumberOfGenerators * varSpecificCapacity,
                        'Owning Business Unit': gblRecordSelectedProject.'Besitzer (Unternehmenseinheit)'
                    }
                )
            },
            Trace(
                $"G001: Patch GeneratorType '{varCreatedGeneratorEntity.Name}':=> {varCreatedGeneratorEntity.GeneratorTypeInProject}",
                TraceSeverity.Information
            );
            With(
                // Ensure new generators in Generator type.
                {
                    varStartIndex: If(
                        IsBlank(colGeneratorsInProjectsTemporary),
                        0,
                        Max(
                            colGeneratorsInProjectsTemporary,
                            Index
                        )
                    )
                },
                ClearCollect(
                    colTemporaryGeneratorList,
                    ForAll(
                        Sequence(Value(txt_GeneratorData_RightPanel_Form_Fields_NumberOfGenerator.Value)),
                        {vsb_name: $"WTG {gblRecordSelectedProject.'Short Name'}_{varStartIndex + ThisRecord.Value}"}
                    )
                );
                Trace(
                    $"G002: Try add generators in project '{gblRecordSelectedProject.'Project Name'}':=> {JSON(colTemporaryGeneratorList)}",
                    TraceSeverity.Information
                );
                ForAll(
                    colTemporaryGeneratorList As Candidate,
                    Patch(
                        GeneratorInProjects,
                        Defaults(GeneratorInProjects),
                        {
                            Name: Candidate.vsb_name,
                            ModuleTypeInProject: varCreatedGeneratorEntity,
                            'Effective Capacity': Value(locNewGeneratorEntity.'Specific Capacity'),
                            'Owning Business Unit': gblRecordSelectedProject.'Besitzer (Unternehmenseinheit)',
                            'Effective Hub Height': Value(locNewGeneratorEntity.'Hub Height')
                        }
                    )
                );
                Trace(
                    $"G003: Add generator type {varCreatedGeneratorEntity.GeneratorTypeInProject} in project '{gblRecordSelectedProject.'Project Name'}' was completed...",
                    TraceSeverity.Information
                );
            );
            With(
                {varCreatedGeneratorEntityGuid: GUID(varCreatedGeneratorEntity.GeneratorTypeInProject)},
                If(
                // Update collection Generator type in Projects.
                    IsBlank(locSelectedGeneratorEntity),
                    Collect(
                        colGeneratorTypeInProjects,
                        AddColumns(
                            LookUp(
                                GeneratorTypeInProjects,
                                GeneratorTypeInProject = varCreatedGeneratorEntityGuid
                            ),
                            IsFolded,
                            false
                        )
                    ),
                    UpdateIf(
                        colGeneratorTypeInProjects,
                        GeneratorTypeInProject = varCreatedGeneratorEntity.GeneratorTypeInProject,
                        AddColumns(
                            varCreatedGeneratorEntity,
                            IsFolded,
                            false
                        )
                    )
                )
            );
            ClearCollect(
                // Fill temporary collection with all generators in generator type.
                colGeneratorsInProjectsTemporary,
                AddColumns(
                    Filter(
                        GeneratorInProjects,
                        And(
                            Not(IsEmpty(colGeneratorTypeInProjects)),
                            AsType(
                                ModuleTypeInProject,
                                GeneratorTypeInProjects
                            ).GeneratorTypeInProject in colGeneratorTypeInProjects.GeneratorTypeInProject
                        )
                    ),
                    GeneartorName,
                    Name,
                    Index,
                    Value(
                        Last(
                            Split(
                                Name,
                                "_"
                            )
                        ).Value
                    )
                )
            );
            If(
                IsBlank(
                    LookUp(
                        colGeneratorTypesPagging,
                        Id = varCreatedGeneratorEntity.GeneratorTypeInProject
                    )
                ),
                With(
                    {varGeneratorsNumber: varCreatedGeneratorEntity.'Number of Generators'},
                    Trace(
                        $"G004: Update pagging collection with new generator type :=> {varCreatedGeneratorEntity.GeneratorTypeInProject}: Num. {varGeneratorsNumber}",
                        TraceSeverity.Information
                    );
                    Collect(
                        colGeneratorTypesPagging,
                        {
                            Id: varCreatedGeneratorEntity.GeneratorTypeInProject,
                            Event: "",
                            TotalRows: varGeneratorsNumber,
                            Page: 1,
                            Pages: RoundUp(
                                varGeneratorsNumber / locGeneratorsPageSize,
                                0
                            ) + If(
                                varGeneratorsNumber = 0,
                                1
                            ),
                            PageSize: locGeneratorsPageSize
                        }
                    )
                );
            );
            If(
                Not(tgl_btn_GeneratorData_RightPanel_Form_Filter_Country.Checked),
                // Start flow to request generaor permissions.
                Trace(
                    $"G005: Start flow :=> {varCreatedGeneratorEntity.GeneratorTypeInProject}",
                    TraceSeverity.Information
                );
                With(
                    {
                        varProject: {
                            ProjectGuid: gblRecordSelectedProject.Project,
                            ProjectId: gblRecordSelectedProject.'Project ID',
                            ProjectName: gblRecordSelectedProject.'Project Name',
                            ShortName: gblRecordSelectedProject.'Short Name',
                            ProjectManagerEmail: gblRecordSelectedProject.'Project Manager'.Mail,
                            ModuleType: gblAppConstants.ModuleType.Generator,
                            GeneratorTypeInProject: varCreatedGeneratorEntity.GeneratorTypeInProject,
                            Generator: varCreatedGeneratorEntity.Generator.Generator
                        }
                    },
                    Set(
                        gblFlowRequestModuleTypeInProject,
                        RequestModulePermission.Run(
                            User().Email,
                            gblPrimarilyApprovalGroupID,
                            gblProjectManagmentAppID,
                            JSON(varProject)
                        )
                    );
                    UpdateIf(
                        colGeneratorTypeInProjects,
                        GeneratorTypeInProject = varCreatedGeneratorEntity.GeneratorTypeInProject,
                        {
                            'Request Permission State': LookUp(
                                Choices('Request Permission State'),
                                Value = gblAppConstants.RequestPermission.PermissionPending
                            ).Value,
                            FlowRunId: gblFlowRequestModuleTypeInProject.runid,
                            FlowApprovalId: gblFlowRequestModuleTypeInProject.approvalid
                        }
                    );
                ),
                // Update project Plant WTG Capacity/Cost only for available geneartors. For requested generators SUM will be calculated in flow, if generator will be approved.
                Trace(
                    $"G007: pdate project Plant WTG Capacity/Cost :=> {varCreatedGeneratorEntity.GeneratorTypeInProject}",
                    TraceSeverity.Information
                );
                With(
                    {
                        varColCurrentRecords: Filter(
                            colGeneratorTypeInProjects,
                            And(
                                Or(
                                    IsBlank('Request Permission State'),
                                    'Request Permission State' = gblAppConstants.RequestPermission.PermissionApproved
                                ),
                                Status = 'Status (GeneratorTypeInProjects)'.Active
                            )
                        )
                    },
                    Trace(
                        $"G007: Generator data {locSelectedGeneratorEntity.Name} was updated, Record to calculate: {CountRows(varColCurrentRecords)}; {JSON(
                            ShowColumns(
                                varColCurrentRecords,
                                Name,
                                'Number of Generators',
                                Status
                            )
                        )}...",
                        TraceSeverity.Information
                    );
                    Set(
                        gblRecordSelectedProject,
                        Patch(
                            Projects,
                            gblRecordSelectedProject,
                            {
                                'Plant WTG Capacity [MW]': Sum(
                                    varColCurrentRecords,
                                    'Generators Capacity'
                                ),
                                'Plant WTG Cost [EUR]': Sum(
                                    varColCurrentRecords,
                                    'Generators Cost'
                                )
                            }
                        )
                    )
                );
            );
            UpdateContext(
                // Set local variable generator type.
                {
                    locSelectedGeneratorEntity: LookUp(
                        colGeneratorTypeInProjects,
                        GeneratorTypeInProject = varCreatedGeneratorEntity.GeneratorTypeInProject
                    )
                }
            );
        )
    );
    Reset(cmb_Supplier);
    Reset(cmb_Supplier_1);
    Reset(cmb_Supplier_2);
    Reset(txt_GeneratorData_RightPanel_Form_Fields_NumberOfGenerator);
    Notify(
        "Generator type was successfully saved for current project!",
        NotificationType.Success,
        2000
    ),
    Notify(
        "Error: Generator type could not be saved. " & "Internal error: originated on " & FirstError.Source & ". Message: " & FirstError.Message & FirstError.Details.HttpResponse,
        NotificationType.Error
    )
);
