                }
            )
        );
        Trace(
            $"EWTG003: Effective Hub Height for selected generator type '{locSelectedGeneratorEntity.Name}' was updated",
            TraceSeverity.Information
        );
    );
    With(
        {
            varFilteredGenerators: Filter(
                GeneratorInProjects,
                AsType(
                    ModuleTypeInProject,
                    GeneratorTypeInProjects
                ).GeneratorTypeInProject = locSelectedGeneratorEntity.GeneratorTypeInProject
            )
        },
        With(
            {
                varRecordGenerator: locSelectedGeneratorEntity.Generator,
                varNumberOfGenerators: CountRows(varFilteredGenerators),
                varSpecificCapacity: locSelectedGeneratorEntity.Generator.'Specific Capacity'
            },
            With(
                {
                    varAccumulatedPrice: gblEstimationPriceInflationDirectConstants.AdditionalCost.AccumulatedIndex,
                    varFoundationCostIncluded: Text(varRecordGenerator.'Foundation cost included'),
                    varAdditionalCost: Value(varRecordGenerator.'Additional foundation cost'),
                    varGeneratorCostsPerWtgNet: Switch(
                        Value(varNumberOfGenerators),
                        1,
                        varRecordGenerator.'1 WTG price',
                        2,
                        varRecordGenerator.'2 WTG price',
                        3,
                        varRecordGenerator.'3 WTG price',
                        4,
                        varRecordGenerator.'4 WTG price',
                        varRecordGenerator.'5 WTG price'
                    )
                },
                If(
                    varFoundationCostIncluded = "Yes",
                    UpdateContext(
                        {
                            locNumberOfGenerators: varNumberOfGenerators,
                            locGeneratorCostsPerWtg: Switch(
                                Value(varNumberOfGenerators),
                                1,
                                varGeneratorCostsPerWtgNet * varAccumulatedPrice,
                                2,
                                varGeneratorCostsPerWtgNet * varAccumulatedPrice,
                                3,
                                varGeneratorCostsPerWtgNet * varAccumulatedPrice,
                                4,
                                varGeneratorCostsPerWtgNet * varAccumulatedPrice,
                                varGeneratorCostsPerWtgNet * varAccumulatedPrice
                            ),
                            locSpecificCapacity: varSpecificCapacity
                        }
                    ),
                    UpdateContext(
                        {
                            locNumberOfGenerators: varNumberOfGenerators,
                            locGeneratorCostsPerWtg: Switch(
                                Value(varNumberOfGenerators),
                                1,
                                (varGeneratorCostsPerWtgNet + varAdditionalCost) * varAccumulatedPrice,
                                2,
                                (varGeneratorCostsPerWtgNet + varAdditionalCost) * varAccumulatedPrice,
                                3,
                                (varGeneratorCostsPerWtgNet + varAdditionalCost) * varAccumulatedPrice,
                                4,
                                (varGeneratorCostsPerWtgNet + varAdditionalCost) * varAccumulatedPrice,
                                (varGeneratorCostsPerWtgNet + varAdditionalCost) * varAccumulatedPrice
                            ),
                            locSpecificCapacity: varSpecificCapacity
                        }
                    )
                )
            )
        )
    );
    With(
        {
            varGenratorTypeCapacity: Sum(
                Filter(
                    GeneratorInProjects,
                    AsType(
                        ModuleTypeInProject,
                        GeneratorTypeInProjects
                    ).GeneratorTypeInProject = locSelectedGeneratorEntity.GeneratorTypeInProject
                ),
                'Effective Capacity'
            )
        },
        UpdateContext(
            {
                locSelectedGeneratorEntity: Patch(
                    colGeneratorTypeInProjects,
                    LookUp(
                        colGeneratorTypeInProjects,
                        GeneratorTypeInProject = locSelectedGeneratorEntity.GeneratorTypeInProject
                    ),
                    {
                        'Number of Generators': locNumberOfGenerators,
                        'Cost per WTG': locGeneratorCostsPerWtg,
                        'Generators Cost': locNumberOfGenerators * locGeneratorCostsPerWtg,
                        'Generators Capacity': varGenratorTypeCapacity
                    }
                )
            }
        );
        Patch(
            colGeneratorTypeInProjects,
            LookUp(
                colGeneratorTypeInProjects,
                GeneratorTypeInProject = locSelectedGeneratorEntity.GeneratorTypeInProject
            ),
            {
                'Number of Generators': locNumberOfGenerators,
                'Cost per WTG': locGeneratorCostsPerWtg,
                'Generators Cost': locNumberOfGenerators * locGeneratorCostsPerWtg,
                'Generators Capacity': varGenratorTypeCapacity
            }
        );
        Patch(
            GeneratorTypeInProjects,
            LookUp(
                GeneratorTypeInProjects,
                GeneratorTypeInProject = locSelectedGeneratorEntity.GeneratorTypeInProject
            ),
            {
                'Number of Generators': locNumberOfGenerators,
                'Cost per WTG': locGeneratorCostsPerWtg,
                'Generators Cost': locNumberOfGenerators * locGeneratorCostsPerWtg,
                'Generators Capacity': varGenratorTypeCapacity
            }
        );
    );
    With(
        {
            varColCurrentRecords: Filter(
                colGeneratorTypeInProjects,
                And(
                    Or(
                        IsBlank('Request Permission State'),
                        'Request Permission State' = gblAppConstants.RequestPermission.PermissionApproved
                    ),
                    Status = 'Status (GeneratorTypeInProjects)'.Active
                )
            )
        },
        Trace(
            $"EWTG004: Generator data {locSelectedGeneratorEntity.Name} was updated, Record to calculate: {CountRows(varColCurrentRecords)}...",
            TraceSeverity.Information
        );
        Set(
            gblRecordSelectedProject,
            Patch(
                Projects,
                gblRecordSelectedProject,
                {
                    'Plant WTG Capacity [MW]': Sum(
                        varColCurrentRecords,
                        'Generators Capacity'
                    ),
                    'Plant WTG Cost [EUR]': Sum(
                        varColCurrentRecords,
                        'Generators Cost'
                    )
                }
            )
        )
    );
    With(
        {
            varFilteredGenerators: AddColumns(
                Filter(
                    GeneratorInProjects,
                    AsType(
                        ModuleTypeInProject,
                        GeneratorTypeInProjects
                    ).GeneratorTypeInProject in colGeneratorTypeInProjects.GeneratorTypeInProject
                ),
                GeneartorName,
                Name,
                Index,
                Value(
                    Last(
                        Split(
                            Name,
                            "_"
                        )
                    ).Value
                )
            )
        },
        ClearCollect(
            colGeneratorsInProjectsTemporary,
            varFilteredGenerators
        )
    );
    With(
        {varGeneratorsGridTotalRows: locSelectedGeneratorEntity.'Number of Generators'},
        UpdateIf(
            colGeneratorTypesPagging,
            Id = locSelectedGeneratorEntity.GeneratorTypeInProject,
            {
                Event: Blank(),
                TotalRows: varGeneratorsGridTotalRows,
                Page: 1,
                Pages: RoundUp(
                    varGeneratorsGridTotalRows / locGeneratorsPageSize,
                    0
                ) + If(
                    varGeneratorsGridTotalRows = 0,
                    1
                ),
                PageSize: locGeneratorsPageSize
            }
        )
    );
    Select(btn_GeneratorData_RightPanel_Form_Generator_Buttons_Reset);
    Notify(
        "Generator was successfully saved for current project!",
        NotificationType.Success,
        gblAppConstants.DefNotifyTimeoutMilliseconds
    ),
    Notify(
        "Error: Generator could not be saved. " & "Internal error: originated on " & FirstError.Source & ". Message: " & FirstError.Message & FirstError.Details.HttpResponse,
        NotificationType.Error
    )
);
If(
    locNewWtgWillbeAllocated,
    UpdateContext(
        {
            locGeneratorTypeInProjectNewlyCreated: Blank(),
            locSingleGeneratorAddedEntity: locSelectedGeneratorInProject
        }
    );
    Select(btn_Trigger_New_AllocateWTGs_To_Land_Lease)
);
UpdateContext(
    {
        locIsVisibleRightPanelNewEditGeneratorInProject: false,
        locIsVisibleGeneratorLongOperationProcessingDialog: false,
        locGeneratorLongOperationProcessingDialogText: Blank(),
        locApplyAllWTGcapacities: false,
        locApplyAllWTGHugHeights: false
    }
);

If(
    CountRows(colGeneratorTypeInProjects) > 0,
    UpdateContext(
        {
            locSelectedGeneratorEntity: First(colGeneratorTypeInProjects),
            locSelectedPvModuleTypeEntity: Blank(),
            locSelectedStorageTypeEntity: Blank(),
            locSelectedHydrogenTypeEntity: Blank(),
            locSelectedSubstationTypeEntity: Blank()
        }
    ),
    CountRows(colPVModuleTypesInProjects) > 0,
    UpdateContext(
        {
            locSelectedPvModuleTypeEntity: First(colPVModuleTypesInProjects),
            locSelectedGeneratorEntity: Blank(),
            locSelectedStorageTypeEntity: Blank(),
            locSelectedHydrogenTypeEntity: Blank(),
            locSelectedSubstationTypeEntity: Blank()
        }
    ),
    CountRows(colHydrogenTypesInProjects) > 0,
    UpdateContext(
        {
            locSelectedHydrogenTypeEntity: First(colHydrogenTypesInProjects),
            locSelectedGeneratorEntity: Blank(),
            locSelectedStorageTypeEntity: Blank(),
            locSelectedPvModuleTypeEntity: Blank(),
            locSelectedSubstationTypeEntity: Blank()
        }
    ),
    CountRows(colStorageTypesInProjects) > 0,
    UpdateContext(
        {
            locSelectedStorageTypeEntity: First(colStorageTypesInProjects),
            locSelectedGeneratorEntity: Blank(),
            locSelectedHydrogenTypeEntity: Blank(),
            locSelectedPvModuleTypeEntity: Blank(),
            locSelectedSubstationTypeEntity: Blank()
        }
    ),
    CountRows(colSubstationTypesInProjects) > 0,
    UpdateContext(
        {
            locSelectedSubstationTypeEntity: First(colSubstationTypesInProjects),
            locSelectedGeneratorEntity: Blank(),
            locSelectedHydrogenTypeEntity: Blank(),
            locSelectedPvModuleTypeEntity: Blank(),
            locSelectedStorageTypeEntity: Blank()
        }
    )
)

With(
    {
        locIsDeviceTypeIsNotPatchedAlready: If(
            !IsBlank(locDeviceTypeTobeCreated_PV),
            IsBlank(
                LookUp(
                    DeviceTypesInProjects,
                    TypeInProject = locDeviceTypeTobeCreated_PV
                )
            ),
            !IsBlank(locDeviceTypeTobeCreated_WTG),
            IsBlank(
                LookUp(
                    DeviceTypesInProjects,
                    TypeInProject = locDeviceTypeTobeCreated_WTG
                )
            ),
            false
        )
    },
    If(
        locIsDeviceTypeIsNotPatchedAlready,
        With(
            {
                locDeviceTypePatched: Patch(
                    DeviceTypesInProjects,
                    Defaults(DeviceTypesInProjects),
                    {
                        Name: Coalesce(
                            locDeviceTypeTobeCreated_WTG,
                            locDeviceTypeTobeCreated_PV
                        ).vsb_name,
                        TypeInProject: Coalesce(
                            locDeviceTypeTobeCreated_WTG,
                            locDeviceTypeTobeCreated_PV
                        ),
                        'Owning Business Unit': Coalesce(
                            locDeviceTypeTobeCreated_WTG,
                            locDeviceTypeTobeCreated_PV
                        ).owningbusinessunit
                    }
                )
            },
            UpdateContext(
                {
                    locDeviceTypeTobeCreated_WTG: Blank(),
                    locDeviceTypeTobeCreated_PV: Blank()
                }
            );
            Trace(
                $"G001: Patch DeviceTypeInProject '{locDeviceTypePatched.Name}':=> {locDeviceTypePatched.DeviceTypesInProject}",
                TraceSeverity.Information
            )
        ),
        UpdateContext(
            {
                locDeviceTypeTobeCreated_WTG: Blank(),
                locDeviceTypeTobeCreated_PV: Blank()
            }
        );
    )
);

With(
    {
        varGeneratorsToCreateInLandLeaseAllocation: If(
            Not(IsBlank(locGeneratorTypeInProjectNewlyCreated)),
            Filter(
                GeneratorInProjects,
                ModuleTypeInProject = locGeneratorTypeInProjectNewlyCreated
            ),
            Not(IsBlank(locSelectedGeneratorInProject)),
            Filter(
                GeneratorInProjects,
                GeneratorInProject = locSelectedGeneratorInProject.GeneratorInProject
            )
        ),
        varLandLeaseCostToBeUpdated: Filter(
            'Land Lease Project Costs',
            Project.Project = gblRecordSelectedProject.Project,
            AllWTGAllocated = 'AllWTGAllocated (Land Lease Project Costs)'.Yes
        )
    },
    With(
        {
            varAllocatedWtgsInSelectedLandLeaseCost: Filter(
                'Land Lease Allocation WTGS',
                'Project Cost'.'Land Lease Project Cost' in varLandLeaseCostToBeUpdated.'Land Lease Project Cost'
            )
        },
        ForAll(
            varLandLeaseCostToBeUpdated As locSelectedLandLeaseCost,
            ForAll(
                varGeneratorsToCreateInLandLeaseAllocation As SelectedGenerator,
                Patch(
                    'Land Lease Allocation WTGS',
                    With(
                        {
                            varAllocatedWtgInSelectedLandLeaseCost: LookUp(
                                varAllocatedWtgsInSelectedLandLeaseCost,
                                And(
                                    'Project Cost'.'Land Lease Project Cost' = locSelectedLandLeaseCost.'Land Lease Project Cost',
                                    'Generator In Project'.GeneratorInProject = SelectedGenerator.GeneratorInProject
                                )
                            )
                        },
                        If(
                            IsBlank(varAllocatedWtgInSelectedLandLeaseCost),
                            Defaults('Land Lease Allocation WTGS'),
                            varAllocatedWtgInSelectedLandLeaseCost
                        )
                    ),
                    {
                        Name: locSelectedLandLeaseCost.'Land Owner' & "-" & locSelectedLandLeaseCost.Description & "-" & SelectedGenerator.Name,
                        'Project Cost': locSelectedLandLeaseCost,
                        'Generator In Project': SelectedGenerator,
                        'Owning Business Unit': gblRecordSelectedProject.'Besitzer (Unternehmenseinheit)'
                    }
                );
            )
        )
    );
    UpdateContext(
        {
            locGeneratorTypeInProjectNewlyCreated: Blank(),
            locSingleGeneratorAddedEntity: Blank(),
            locNewWtgWillbeAllocated: Blank()
        }
    );

)
